/* Observe the actual outgoing duplicate packet as well as helper completion. */
static unsigned duplicate_packets;static uint8_t *duplicate_packet;static uint32_t duplicate_packet_size;
int sidepanel_send(const wchar_t *,uint32_t,const void *,uint32_t);
int dock_test_sidepanel_send(const wchar_t *app,uint32_t type,const void *data,uint32_t size){
 if(type==PANELP_DUPLICATE_OPEN&&!_wcsicmp(app,duplicate_app())){duplicate_packets++;free(duplicate_packet);duplicate_packet=malloc(size);duplicate_packet_size=duplicate_packet?size:0;if(duplicate_packet)memcpy(duplicate_packet,data,size);}
 return sidepanel_send(app,type,data,size);
}
static int duplicate_done(void){uint64_t end=GetTickCount64()+10000;while(g_duplicate_state.state<4&&GetTickCount64()<end)pump(5);return g_duplicate_state.state==4&&!g_duplicate_state.errors;}
static int select_duplicate_folders(Pane *p,unsigned n){p_clear_sel(p);for(unsigned i=0;i<n;i++){wchar_t name[32];swprintf(name,32,L"dup-%02u",i);uint32_t row=fpe_view_find(p->view,name);if(row==UINT32_MAX)return 0;p_set_sel(p,row,1);if(!i)p->cursor=row;}p_redraw(p);return p->nsel==n;}
static int packet_roots(const wchar_t *base,unsigned n){
 if(!duplicate_packet||duplicate_packet_size<sizeof(duplicate_open))return 0;duplicate_open h;memcpy(&h,duplicate_packet,sizeof h);if(h.count!=n||h.session!=g_duplicate_request.session)return 0;size_t offset=sizeof h;
 for(unsigned i=0;i<n;i++){wchar_t expected[32768];swprintf(expected,32768,L"%ls\\dup-%02u",base,i);size_t chars=wcslen(expected)+1,bytes=chars*2;if(h.chars[i]!=chars||offset+bytes>duplicate_packet_size||memcmp(duplicate_packet+offset,expected,bytes)||wcscmp(g_duplicate_roots[i],expected))return 0;offset+=bytes;}
 return offset==duplicate_packet_size;
}
